"""Native generation proxy with a fixed, installation-relative child owner.

The input contains only three native code bodies. All role targets and exports
are fixed here; generation requests never select a function pointer.
"""
from pathlib import Path
import struct
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_artifact_publication import document
from tools import generate_hia_clang_value_packer as base
from tools import generate_hia_native_fixed_component_packer as loader
ROOT=Path(__file__).resolve().parents[1]
PROXY=bytes.fromhex('')
COMPONENT=bytes.fromhex('')
COMPONENT_AT=(len(PROXY)+7)&~7
_buf=bytearray(PROXY+bytes(COMPONENT_AT-len(PROXY))+COMPONENT)
for at,target in ((589,COMPONENT_AT+1575),(614,COMPONENT_AT+29),(639,COMPONENT_AT)):
    assert _buf[at:at+4]==bytes(4)
    struct.pack_into('<i',_buf,at,target-at-4)
BRIDGE=bytes(_buf)
ROLES=('proxy','component','loader')
MAGIC=int.from_bytes(b'HIAGPRP1','little')
FIXUPS=(('proxy',443),('component',COMPONENT_AT+995),('loader',COMPONENT_AT+1309))
ENTRY_OFFSETS={}
LENGTH_FIXUPS=()
DYNAMIC_RELOCATIONS=tuple(('loader',at,name)for at,name in loader.RELOCATIONS)
IMPORTS=loader.IMPORTS
EXPORT='hia_generation_lease_owner_generation_proxy'
EXPORT_SIZE=745
BRIDGE_EXPORTS={
 '@close':[5,740], '@owner':[745,len(PROXY)-745],
 '@component':[COMPONENT_AT,1575],
 '@prepare':[COMPONENT_AT+13,1575-13],
 '@exception':[COMPONENT_AT+21,1575-21],
 '@generation':[COMPONENT_AT+29,1575-29],
 '@bind_owner':[COMPONENT_AT+1575,len(COMPONENT)-1575],
}
EXTRA_EXPORTS=(
 ('hia_generation_lease_owner_generation_proxy_close','@close'),
 ('hia_generation_lease_owner_generation_proxy_owner','@owner'),
 ('hia_generation_lease_owner_component','@component'),
 ('hia_generation_lease_owner_component_prepare','@prepare'),
 ('hia_generation_lease_owner_component_exception','@exception'),
 ('hia_generation_lease_owner_component_generation','@generation'),
 ('hia_generation_lease_owner_component_bind_owner','@bind_owner'),
)
def call(fn,*args):
    names=('ROLES','MAGIC','BRIDGE','FIXUPS','ENTRY_OFFSETS','LENGTH_FIXUPS',
      'DYNAMIC_RELOCATIONS','IMPORTS','EXPORT','EXPORT_SIZE','EXTRA_EXPORTS','BRIDGE_EXPORTS')
    saved={n:getattr(base,n)for n in names}
    try:
        for n in names:setattr(base,n,globals()[n])
        return fn(*args)
    finally:
        for n,v in saved.items():setattr(base,n,v)
def source_program():return call(base.source_program)
def reference_object(parts):return call(base.reference_object,parts)
def reference_flat(parts):return call(base.reference_flat,parts)
def main():
    tree=document(source_program(),'generation_lease_owner_generation_proxy_packer')
    path=ROOT/'examples/hia_bootstrap/generation_lease_owner_generation_proxy_packer.hepta'
    path.write_text(render_assembly(tree))
    print(path.name,path.stat().st_size,len(tree['functions']),
      sum(len(f['blocks'])for f in tree['functions']),flush=True)
if __name__=='__main__':main()
